import { apiFetch, ApiError, clearToken, isSignedIn } from "./api.js";
import { clear, el, formatTime, showMessage } from "./ui.js";

if (!isSignedIn()) {
window.location.href = "login.html";
}

const PAGE_SIZE = 20;

const listNode = document.getElementById("list");
const addForm = document.getElementById("add-form");
const filterNode = document.getElementById("filter");
const prevButton = document.getElementById("prev");
const nextButton = document.getElementById("next");
const pageInfo = document.getElementById("page-info");
const whoNode = document.getElementById("who");
const signoutButton = document.getElementById("signout");

let offset = 0;
let total = 0;

function errorText(error) {
return error instanceof ApiError ? error.message : "The service cannot be reached.";
}

function handleError(error) {
if (error instanceof ApiError && error.status === 401) {
clearToken();
window.location.href = "login.html";
return;
}
showMessage(errorText(error), "error");
}

async function loadUser() {
try {
const user = await apiFetch("/api/auth/me");
whoNode.textContent = user.username;
} catch (error) {
handleError(error);
}
}

async function toggle(todo) {
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { done: !todo.done } });
await loadTodos();
} catch (error) {
handleError(error);
}
}

async function rename(todo) {
const title = window.prompt("New title", todo.title);
if (title === null) {
return;
}
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { title } });
await loadTodos();
} catch (error) {
handleError(error);
}
}

async function remove(todo) {
if (!window.confirm(`Delete "${todo.title}"?`)) {
return;
}
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "DELETE" });
if (offset > 0 && offset >= total - 1) {
offset = Math.max(0, offset - PAGE_SIZE);
}
await loadTodos();
} catch (error) {
handleError(error);
}
}

function renderTodo(todo) {
const checkbox = el("input", { type: "checkbox", checked: todo.done ? "checked" : null });
checkbox.addEventListener("change", () => toggle(todo));
const title = el("span", { class: "title" }, todo.title);
const meta = el("span", { class: "muted" }, formatTime(todo.created_at));
const renameButton = el("button", { type: "button", class: "secondary" }, "Rename");
renameButton.addEventListener("click", () => rename(todo));
const deleteButton = el("button", { type: "button", class: "danger" }, "Delete");
deleteButton.addEventListener("click", () => remove(todo));
return el(
"div",
{ class: `list-item${todo.done ? " done" : ""}` },
checkbox,
el("div", { class: "grow" }, title, meta),
renameButton,
deleteButton,
);
}

async function loadTodos() {
const query = { limit: PAGE_SIZE, offset };
const filter = filterNode.value;
if (filter === "open") {
query.done = "false";
} else if (filter === "done") {
query.done = "true";
}
try {
const page = await apiFetch("/api/todos", { query });
total = page.total;
clear(listNode);
if (page.items.length === 0) {
listNode.append(el("p", { class: "muted" }, "No todos yet."));
}
for (const todo of page.items) {
listNode.append(renderTodo(todo));
}
const from = total === 0 ? 0 : offset + 1;
const to = offset + page.items.length;
pageInfo.textContent = `${from}-${to} of ${total}`;
prevButton.disabled = offset === 0;
nextButton.disabled = offset + PAGE_SIZE >= total;
} catch (error) {
handleError(error);
}
}

addForm.addEventListener("submit", async (event) => {
event.preventDefault();
const input = document.getElementById("add-title");
const title = input.value.trim();
if (!title) {
return;
}
try {
await apiFetch("/api/todos", { method: "POST", body: { title } });
input.value = "";
offset = 0;
await loadTodos();
} catch (error) {
handleError(error);
}
});

filterNode.addEventListener("change", () => {
offset = 0;
loadTodos();
});

prevButton.addEventListener("click", () => {
offset = Math.max(0, offset - PAGE_SIZE);
loadTodos();
});

nextButton.addEventListener("click", () => {
offset += PAGE_SIZE;
loadTodos();
});

signoutButton.addEventListener("click", () => {
clearToken();
window.location.href = "login.html";
});

await loadUser();
await loadTodos();
